//! let command = resolve_string("rails s -e ${mode}", &ctx).unwrap();
//! assert_eq!(command, "rails s -e development");
//! ```
//!
//! For file-based config loading, see the integration tests.

pub mod cache;
pub mod cli;
pub mod config;
pub mod detection;
pub mod environment;
pub mod error;
pub mod feedback;
pub mod lint;
pub mod registry;
