 395→    }
 396→
 397→    fn make_resolved_step(requires: Vec<String>) -> ResolvedStep {
 398→        let config = StepConfig {
 399→            command: Some("echo test".to_string()),
 400→            requires,
 401→            ..Default::default()
 402→        };
 403→        ResolvedStep::from_config("test", &config, None)
 404→    }
 405→
 406→    #[test]
 407→    fn unknown_requirement_returns_unknown() {
 408→        let registry = RequirementRegistry::new();
 409→        let probe = make_probe();
 410→        let temp = TempDir::new().unwrap();
 411→        let mut checker = GapChecker::new(&registry, &probe, temp.path());
 412→
 413→        let status = checker.check_one("nonexistent-tool-xyz");
 414→        assert!(matches!(status, RequirementStatus::Unknown));
 415→    }
 416→
 417→    #[test]
 418→    fn gap_checker_caches_results() {
 419→        let registry = RequirementRegistry::new();
 420→        let probe = make_probe();
 421→        let temp = TempDir::new().unwrap();
 422→        let mut checker = GapChecker::new(&registry, &probe, temp.path());
 423→
 424→        // First check
 425→        let status1 = checker.check_one("nonexistent-tool-xyz");
 426→        assert!(matches!(status1, RequirementStatus::Unknown));
 427→
 428→        // Second check should use cache (same result)
 429→        let status2 = checker.check_one("nonexistent-tool-xyz");
 430→        assert!(matches!(status2, RequirementStatus::Unknown));
 431→
 432→        // Verify it's actually cached
 433→        assert!(checker.cache.contains_key("nonexistent-tool-xyz"));
 434→    }
 435→
 436→    #[test]
 437→    fn gap_checker_invalidate_clears_cache() {
 438→        let registry = RequirementRegistry::new();
 439→        let probe = make_probe();
 440→        let temp = TempDir::new().unwrap();
 441→        let mut checker = GapChecker::new(&registry, &probe, temp.path());
 442→
 443→        checker.check_one("nonexistent-tool-xyz");
 444→        assert!(checker.cache.contains_key("nonexistent-tool-xyz"));
 445→
 446→        checker.invalidate("nonexistent-tool-xyz");
 447→        assert!(!checker.cache.contains_key("nonexistent-tool-xyz"));
 448→    }
 449→
 450→    #[test]
 451→    fn gap_checker_invalidate_all_clears_all() {
 452→        let registry = RequirementRegistry::new();
 453→        let probe = make_probe();
 454→        let temp = TempDir::new().unwrap();
 455→        let mut checker = GapChecker::new(&registry, &probe, temp.path());
 456→
 457→        checker.check_one("nonexistent-tool-xyz");
 458→        checker.check_one("another-fake-tool");
 459→        assert_eq!(checker.cache.len(), 2);
 460→
 461→        checker.invalidate_all();
 462→        assert!(checker.cache.is_empty());
 463→    }
 464→
 465→    #[test]
 466→    fn check_step_with_provided_skips_requirements() {
 467→        let registry = RequirementRegistry::new();
 468→        let probe = make_probe();
 469→        let temp = TempDir::new().unwrap();
 470→        let mut checker = GapChecker::new(&registry, &probe, temp.path());
 471→
 472→        let step = make_resolved_step(vec!["ruby".to_string(), "postgres-server".to_string()]);
 473→
 474→        let mut provided = HashSet::new();
 475→        provided.insert("postgres-server".to_string());
 476→
 477→        let gaps = checker.check_step(&step, Some(&provided));
 478→
 479→        // postgres-server should be skipped (provided)
 480→        // ruby should be checked (and will likely be Missing or Satisfied depending on system)
 481→        assert!(!gaps.iter().any(|g| g.requirement == "postgres-server"));
 482→    }
 483→
 484→    #[test]
 485→    fn check_step_with_none_provided_checks_all() {
 486→        let registry = RequirementRegistry::new();
 487→        let probe = make_probe();
