 489→        let mut checker = GapChecker::new(&registry, &probe, temp.path());
 490→
 491→        let step = make_resolved_step(vec!["nonexistent-tool-xyz".to_string()]);
 492→
 493→        let gaps = checker.check_step(&step, None);
 494→
 495→        // Should check nonexistent-tool-xyz and return Unknown
 496→        assert_eq!(gaps.len(), 1);
 497→        assert_eq!(gaps[0].requirement, "nonexistent-tool-xyz");
 498→        assert!(matches!(gaps[0].status, RequirementStatus::Unknown));
