 533→    // --- 1D: Dependency resolution tests ---
 534→
 535→    #[test]
 536→    fn ruby_depends_on_mise_when_no_manager() {
 537→        let registry = RequirementRegistry::new();
 538→        let probe = make_probe();
 539→        let temp = TempDir::new().unwrap();
