 723→    #[test]
 724→    fn manager_check_falls_through_to_missing() {
 725→        // A known tool that is NOT installed on the system should return Missing
 726→        // when none of its checks succeed. Using "nonexistent-tool-xyz" which is
 727→        // unknown → returns Unknown. Instead, we test that a real registered tool
 728→        // with no passing checks falls through to Missing.
 729→        let registry = RequirementRegistry::new();
 730→        let probe = make_probe();
 731→        let temp = TempDir::new().unwrap();
 732→        let mut checker = GapChecker::new(&registry, &probe, temp.path());
 733→
 734→        // "ruby" is a known requirement in the registry. On a system without ruby,
 735→        // it would return Missing. On a system with ruby, it returns Satisfied.
 736→        // We can verify the logic by checking the evaluate method behavior:
 737→        // - Unknown tools → RequirementStatus::Unknown
 738→        // - Known tools with no passing checks → RequirementStatus::Missing
 739→        let unknown_status = checker.check_one("nonexistent-tool-xyz");
 740→        assert!(
 741→            matches!(unknown_status, RequirementStatus::Unknown),
 742→            "unknown tool should return Unknown, not Missing"
 743→        );
 744→
 745→        // A known tool should never return Unknown
 746→        let ruby_status = checker.check_one("ruby");
 747→        assert!(
 748→            !matches!(ruby_status, RequirementStatus::Unknown),
 749→            "known tool 'ruby' should return Satisfied, Missing, or another status — never Unknown"
 750→        );
 751→    }
