 755→    #[test]
 756→    fn manager_detected_but_tool_not_installed_falls_through() {
 757→        // Scenario: A version file (.ruby-version) exists, a manager (mise)
 758→        // is detected as inactive, but the tool binary (ruby) does NOT exist
 759→        // under the manager's install path. The checker should fall through
 760→        // to Missing, not report Inactive.
 761→        //
 762→        // We create a tempdir with a .ruby-version file. The probe has no
 763→        // env vars, so augmented_path is whatever the system has. Since we
 764→        // use a nonexistent tool name that maps to a ManagedCommand check,
 765→        // we build a custom requirement with managed_path_patterns that
 766→        // won't match any real paths. The tool binary won't be found
 767→        // anywhere, so the ManagedCommand check returns None, and the
 768→        // evaluate method falls through to Missing.
 769→        use crate::requirements::registry::{Requirement, RequirementCheck};
 770→
 771→        let temp = TempDir::new().unwrap();
 772→        // Create a version file so the managed command check looks for a manager
 773→        std::fs::write(temp.path().join(".ruby-version"), "3.2.0").unwrap();
 774→
 775→        let probe = make_probe();
 776→        let mut registry = RequirementRegistry::new();
 777→
 778→        // Register a custom requirement that uses ManagedCommand with a
 779→        // tool binary name that definitely doesn't exist on any PATH
 780→        registry.insert(
 781→            "fake-ruby".to_string(),
 782→            Requirement {
 783→                name: "fake-ruby".to_string(),
 784→                checks: vec![RequirementCheck::ManagedCommand {
 785→                    command: "bivvy-nonexistent-ruby-xyz-12345".to_string(),
 786→                    managed_path_patterns: vec!["mise/".to_string(), "rbenv/".to_string()],
 787→                    system_path_patterns: vec!["/usr/bin/".to_string()],
 788→                    version_file: Some(".ruby-version".to_string()),
 789→                }],
 790→                install_template: Some("mise-ruby".to_string()),
 791→                install_hint: Some("Install Ruby via mise".to_string()),
 792→                depends_on: vec![],
 793→                install_requires: None,
 794→            },
 795→        );
 796→
 797→        let mut checker = GapChecker::new(&registry, &probe, temp.path());
 798→
 799→        let status = checker.check_one("fake-ruby");
 800→        // The tool binary doesn't exist anywhere, so ManagedCommand check
 801→        // returns None, and evaluate falls through to Missing.
 802→        assert!(
 803→            matches!(status, RequirementStatus::Missing { .. }),
 804→            "Expected Missing when tool binary not found, got: {:?}",
 805→            status
 806→        );
 807→    }
