    #[test]
    fn extends_child_yaml_replaces_parent_ci_environment_block() {
        let server = MockServer::start();

        // Parent config: step "setup" with ci environment override
        let parent_yaml = r#"
app_name: ParentApp
steps:
  setup:
    command: "parent-default-cmd"
    environments:
      ci:
        command: "parent-ci-cmd"
