#[test]
fn ruby_depends_on_mise_when_no_manager() {
    let registry = RequirementRegistry::new();
    let probe = make_probe();
    let temp = TempDir::new().unwrap();
    let checker = GapChecker::new(&registry, &probe, temp.path());

